import Foundation

/// The `~/Mochlet/Knowledge` layout and its generated files.
public enum BundleLayout {
    public static let directories = ["inbox", "entities", "concepts", "syntheses", "meta", "projects", "meetings", "notes", "signals", "memories"]
    public static let inbox = "inbox", entities = "entities", concepts = "concepts", syntheses = "syntheses", meta = "meta"
    public static let projects = "projects", meetings = "meetings", notes = "notes", signals = "signals", memories = "memories"
    public static let referencesDir = "references"
    public static let schemaFile = "SCHEMA.md"
    public static let agentCopies = ["CLAUDE.md", "AGENTS.md"]
    public static let ignoredDirectories: Set<String> = [".obsidian", ".git", ".trash", "node_modules"]
    public static let generator = "mochlet/2.0"

    public static func isReserved(_ fileName: String) -> Bool {
        fileName == "index.md" || fileName == "log.md" || fileName == ".abstract.md" || fileName == ".overview.md"
    }

    /// Pages Mochlet indexes: `.md` files that are not reserved, not under references/, not hidden.
    public static func isPage(_ relativePath: String) -> Bool {
        let parts = relativePath.split(separator: "/").map(String.init)
        guard let name = parts.last, name.hasSuffix(".md"), !isReserved(name), !name.hasPrefix(".") else { return false }
        if parts.contains(referencesDir) { return false }
        if parts.dropLast().contains(where: { ignoredDirectories.contains($0) || $0.hasPrefix(".") }) { return false }
        if parts.count == 1, [schemaFile, "CLAUDE.md", "AGENTS.md", "README.md"].contains(name) { return false }
        return true
    }

    /// The folder for a page type.
    public static func directory(forType type: String) -> String {
        switch type {
        case "report": return "inbox"
        case "entity": return "entities"
        case "concept", "comparison", "overview": return "concepts"
        case "synthesis": return "syntheses"
        case "lint": return "meta"
        case "meeting": return "meetings"
        case "note": return "notes"
        case "digest": return "signals"
        case "project": return "projects"
        default: return "inbox"
        }
    }

    public static let typeOrder = ["overview", "report", "entity", "concept", "comparison", "synthesis", "project", "meeting", "note", "digest", "transcript", "lint", "memory"]

    public static func sectionTitle(forType type: String) -> String {
        switch type {
        case "report": return "Reports"
        case "entity": return "Entities"
        case "concept": return "Concepts"
        case "comparison": return "Comparisons"
        case "synthesis": return "Syntheses"
        case "overview": return "Overviews"
        case "project": return "Projects"
        case "meeting": return "Meetings"
        case "note": return "Notes"
        case "digest": return "Digests"
        case "transcript": return "Transcripts"
        case "lint": return "Lint reports"
        case "memory": return "Memories"
        default: return type.prefix(1).uppercased() + type.dropFirst() + " pages"
        }
    }
}

// MARK: - index.md

public struct IndexEntry: Equatable, Sendable {
    public var path: String        // relative to the directory being indexed
    public var title: String
    public var description: String?
    public var type: String
    public var sourceCount: Int
    public var status: String?
    public init(path: String, title: String, description: String? = nil, type: String, sourceCount: Int = 0, status: String? = nil) {
        self.path = path
        self.title = title
        self.description = description
        self.type = type
        self.sourceCount = sourceCount
        self.status = status
    }
}

public struct IndexSubdirectory: Equatable, Sendable {
    public var name: String
    public var abstract: String?
    public var pageCount: Int
    public init(name: String, abstract: String? = nil, pageCount: Int = 0) {
        self.name = name
        self.abstract = abstract
        self.pageCount = pageCount
    }
}

/// The reserved, regenerated `index.md` of a directory (OKF §6).
public enum OKFIndexFile {
    public static let marker = "<!-- generated by mochlet; the pages are the source of truth, edits here are overwritten -->"

    public static func render(directory: String, title: String, entries: [IndexEntry], subdirectories: [IndexSubdirectory], isRoot: Bool, now: Date = Date()) -> String {
        var fm = OKFFrontmatter(type: "index", title: title)
        fm.description = isRoot ? "What this knowledge base contains, by page type." : "Pages in \(directory)/."
        if isRoot { fm.okfVersion = "0.2" }
        fm.generated = OKFStamp(by: BundleLayout.generator, at: now)
        var body = marker + "\n\n# \(title)\n\n"
        if isRoot {
            body += "Read this file first; search (`find`/`search`) only when the index does not answer. Pages link to each other with [[wikilinks]]; `references/` holds raw sources that are never edited.\n\n"
        }
        let grouped = Dictionary(grouping: entries, by: \.type)
        var counts: [String] = []
        for t in BundleLayout.typeOrder where grouped[t] != nil { counts.append("\(grouped[t]!.count) \(BundleLayout.sectionTitle(forType: t).lowercased())") }
        for t in grouped.keys.sorted() where !BundleLayout.typeOrder.contains(t) { counts.append("\(grouped[t]!.count) \(t)") }
        if !counts.isEmpty { body += counts.joined(separator: " · ") + "\n\n" }
        let orderedTypes = BundleLayout.typeOrder.filter { grouped[$0] != nil } + grouped.keys.filter { !BundleLayout.typeOrder.contains($0) }.sorted()
        for t in orderedTypes {
            body += "## \(BundleLayout.sectionTitle(forType: t))\n\n"
            for e in grouped[t]!.sorted(by: { $0.title.localizedCaseInsensitiveCompare($1.title) == .orderedAscending }) {
                var line = "* [\(e.title.replacingOccurrences(of: "]", with: "\\]"))](\(e.path))"
                if let d = e.description, !d.isEmpty { line += " - \(OneLine.collapse(d, limit: 160))" }
                var meta: [String] = []
                if e.sourceCount > 0 { meta.append("sources: \(e.sourceCount)") }
                if let s = e.status, s != "stable" { meta.append(s) }
                if !meta.isEmpty { line += " (\(meta.joined(separator: ", ")))" }
                body += line + "\n"
            }
            body += "\n"
        }
        if !subdirectories.isEmpty {
            body += "## Folders\n\n"
            for s in subdirectories.sorted(by: { $0.name < $1.name }) {
                var line = "* [\(s.name)/](\(s.name)/index.md)"
                if let a = s.abstract, !a.isEmpty { line += " - \(OneLine.collapse(a, limit: 160))" }
                if s.pageCount > 0 { line += " (\(s.pageCount) pages)" }
                body += line + "\n"
            }
            body += "\n"
        }
        if entries.isEmpty, subdirectories.isEmpty { body += "_Nothing here yet._\n" }
        return OKFDocument(frontmatter: fm, body: body).serialize()
    }
}

// MARK: - log.md

/// The reserved `log.md` (OKF §7): `## YYYY-MM-DD` headings newest first, one grep-able line per event.
public enum OKFLogFile {
    public static func empty(title: String = "Log") -> String {
        var fm = OKFFrontmatter(type: "log", title: title)
        fm.description = "What Mochlet did in this folder, newest first."
        return OKFDocument(frontmatter: fm, body: "# \(title)\n").serialize()
    }

    /// Appends `- HH:MM kind | text` under today's heading (created at the top when missing).
    public static func append(_ existing: String?, kind: String, text: String, now: Date = Date(), timeZone: TimeZone = .current) -> String {
        var doc = (try? OKFDocument.parse(existing ?? "")) ?? OKFDocument(frontmatter: OKFFrontmatter(type: "log", title: "Log"), body: "# Log\n")
        let day = OKFDate.day(now, timeZone: timeZone)
        let f = DateFormatter()
        f.locale = Locale(identifier: "en_US_POSIX")
        f.timeZone = timeZone
        f.dateFormat = "HH:mm"
        let line = "- \(f.string(from: now)) \(kind) | \(OneLine.collapse(text, limit: 200))"
        var lines = doc.body.split(separator: "\n", omittingEmptySubsequences: false).map(String.init)
        if let h = lines.firstIndex(of: "## \(day)") {
            var insertAt = h + 1
            while insertAt < lines.count, lines[insertAt].hasPrefix("- ") { insertAt += 1 }
            lines.insert(line, at: insertAt)
        } else {
            // After the H1 (and its blank line) when present, else at the top.
            var at = 0
            if let h1 = lines.firstIndex(where: { $0.hasPrefix("# ") }) { at = h1 + 1 }
            while at < lines.count, lines[at].trimmingCharacters(in: .whitespaces).isEmpty { at += 1 }
            lines.insert(contentsOf: ["## \(day)", line, ""], at: at)
            if at > 0, !lines[at - 1].isEmpty { lines.insert("", at: at) }
        }
        doc.body = lines.joined(separator: "\n")
        return doc.serialize()
    }
}

// MARK: - Sidecars

/// `.abstract.md` (≤ 256 chars) and `.overview.md` (≤ 4000 chars) per directory, OpenViking-style.
public enum Sidecar {
    public static let abstractLimit = 256
    public static let overviewLimit = 4000

    public static func render(directory: String, abstract: String, overview: String, total: Int, sampled: Int, now: Date = Date()) -> (abstract: String, overview: String) {
        func fm(_ kind: String) -> String {
            var m: [YAMLPair] = [YAMLPair("directory", .string(directory)), YAMLPair("source", .string(kind))]
            m.append(YAMLPair("generated_by", .mapping([YAMLPair("component", .string(BundleLayout.generator)), YAMLPair("trigger", .string("index"))])))
            m.append(YAMLPair("generated_at", .string(OKFDate.format(now))))
            m.append(YAMLPair("freshness", .mapping([YAMLPair("total", .int(total)), YAMLPair("sampled", .int(sampled)), YAMLPair("unsampled", .int(max(0, total - sampled))), YAMLPair("pending_child_changes", .int(0))])))
            return "---\n" + YAMLLite.emit(.mapping(m)) + "---\n\n"
        }
        return (fm("abstract") + String(abstract.prefix(abstractLimit)) + "\n", fm("overview") + String(overview.prefix(overviewLimit)) + "\n")
    }

    /// A deterministic sample of at most `limit` children (stable across runs for the same set).
    public static func sample(_ children: [String], limit: Int = 32) -> [String] {
        guard children.count > limit else { return children.sorted() }
        let sorted = children.sorted()
        let step = Double(sorted.count) / Double(limit)
        return (0..<limit).map { sorted[Int(Double($0) * step)] }
    }
}

// MARK: - Bootstrap

/// Creates the folders, the schema and the reserved files a new bundle needs.
public enum BundleBootstrap {
    public struct File: Equatable, Sendable {
        public var relativePath: String
        public var contents: String
    }

    /// Files to create when missing (never overwrites).
    public static func files(now: Date = Date()) -> [File] {
        var out: [File] = []
        out.append(File(relativePath: BundleLayout.schemaFile, contents: schema))
        for c in BundleLayout.agentCopies {
            out.append(File(relativePath: c, contents: "<!-- copy of SCHEMA.md for coding agents opened in this folder; Mochlet keeps the two in sync -->\n\n" + schema))
        }
        out.append(File(relativePath: "log.md", contents: OKFLogFile.empty(title: "Knowledge log")))
        out.append(File(relativePath: ".gitignore", contents: ".obsidian/workspace*\n.DS_Store\n.trash/\n.index.sqlite*\n"))
        for d in BundleLayout.directories {
            out.append(File(relativePath: "\(d)/index.md", contents: OKFIndexFile.render(directory: d, title: d.prefix(1).uppercased() + d.dropFirst(), entries: [], subdirectories: [], isRoot: false, now: now)))
        }
        out.append(File(relativePath: "memories/profile.md", contents: profile(now: now)))
        return out
    }

    static func profile(now: Date) -> String {
        var fm = OKFFrontmatter(type: "memory", title: "Profile", description: "Who the owner of this knowledge base is and how they like things.")
        fm.generated = OKFStamp(by: BundleLayout.generator, at: now)
        fm.status = "draft"
        return OKFDocument(frontmatter: fm, body: "# Profile\n\nMochlet fills this in from conversations; edit it freely.\n").serialize()
    }

    public static let schema = """
    ---
    type: schema
    title: Knowledge base schema
    description: How this wiki is organised and how to work in it (for Mochlet and for coding agents).
    ---
    # Knowledge base schema

    This folder is an **LLM-maintained wiki** over immutable sources. Raw material lives under
    `references/`; everything else is a page that compounds: each new source gets a report, and
    the entities and concepts it touches are revised, so the wiki stays current instead of
    becoming a pile of chunks.

    ## Layers

    1. **references/** inside each folder: mirrored files, HTML snapshots, transcripts. Read them,
       never edit them. File names start with 12 hex characters of the source's SHA-256.
    2. **Pages** (`*.md` with YAML frontmatter): what Mochlet and you write.
    3. **This schema** (`SCHEMA.md`, copied to `CLAUDE.md` and `AGENTS.md`).

    ## Folders and page types

    | Folder | `type` | What goes there |
    |---|---|---|
    | `inbox/` | `report` | one page per ingested source: summary, key points, why it matters, entities, action items, quotes |
    | `entities/` | `entity` | people, organisations, products, models, papers; revised whenever a new source mentions them |
    | `concepts/` | `concept`, `comparison`, `overview` | cross-source syntheses with [[wikilinks]] to reports and entities |
    | `syntheses/` | `synthesis` | filed answers: the question is the title, `sources[]` are the citations |
    | `projects/<slug>/` | `project` + pages | material filed to a project (same structure inside) |
    | `meetings/` | `meeting` | one page per meeting, linking its transcript |
    | `notes/YYYY/MM/DD.md` | `note` | dated notes with `## HH:MM` entries |
    | `signals/` | `digest` | daily AI-news digests |
    | `memories/` | `memory` | profile, preferences, dated events (`memories/events/YYYY/MM/DD/*.md`) |
    | `meta/` | `lint` | lint reports with proposed fixes |

    ## Frontmatter (OKF 0.2)

    Every page starts with `---` YAML `---`. `type` is required and non-empty. Recommended:
    `title`, `description` (one sentence; the index shows it), `tags`, `resource` (the canonical
    URL or `file://` path), `status` (`draft` | `stable` | `deprecated`), `stale_after`.
    Trust fields: `sources: [{id, resource, title, author, last_modified}]`,
    `generated: {by, at}`, `verified: [{by, at}]`. Actors are `human:<name>`, `process:<id>` or
    `<producer>/<version>` (Mochlet writes `mochlet/2.0`). Dates are ISO-8601 with an offset.
    Mochlet's own fields live under one key, `mochlet:` (kind, sha256, canonical_url, project…).
    Unknown keys are preserved as they are.

    `index.md` and `log.md` are reserved and regenerated: never edit them by hand.
    `.abstract.md` (≤ 256 chars) and `.overview.md` (≤ 4000 chars) summarise a folder.

    ## Naming and linking

    * File names are ASCII slugs of the title (non-ASCII letters are transliterated), ≤ 60 chars.
    * Link pages with `[[Page title]]` or `[[file-name]]` (Obsidian rules: any page in the vault
      by file name or title; `[[Page|alias]]`, `[[Page#Heading]]`; `![[file]]` embeds a reference).
      Every link should have a backlink: when you mention an entity page, add the mentioning page
      to its `## Mentioned in` list.
    * Cite sources with `[^src]` footnotes inside reports and `sources[]` in frontmatter.

    ## Workflows

    * **Ingest** (Mochlet, on a drop or `add_resource`): mirror → extract → report page in `inbox/`
      (or the project) → integrate: revise up to 15 related entity/concept pages, create missing
      ones, add links both ways → log line → index.
    * **Query**: read `index.md` first; then `find` (lexical + vector, no LLM) or `search`
      (rewritten queries, answer with `[n]` citations). A good answer is filed as a `synthesis`.
    * **Lint** (on demand and weekly): orphans, entities mentioned in ≥ 3 pages without a page,
      broken links, missing backlinks, reports never integrated, contradictions → `meta/lint-*.md`.

    ## Generated vs human-owned

    A page is **human-owned** when a human verified it (`verified[].by` starts with `human:`),
    its `generated.by` is a human, or it has no `generated` stamp at all. Mochlet never rewrites a
    human-owned page; it appends a `## Proposed update (YYYY-MM-DD)` block instead, which you can
    accept from the Knowledge card. Generated pages may be revised freely; add
    `verified: [{by: human:you, at: …}]` to freeze one.

    ## For coding agents

    Mochlet exposes this bundle over MCP (`find`, `search`, `read`, `list`, `tree`, `grep`,
    `add_resource`, `projects`). Prefer `find` for a quick lookup, `search` for an answer with
    citations, and `add_resource` to file something you found. Keep to the conventions above
    when you write pages here.
    """
}
